    value: member.userId,
    label: member.user.name,
    description: member.user.email,
  }));

  return (
    <Combobox
      value={props.value}
      options={options}
      placeholder={props.disabled === true ? "Assignee locked" : "Unassigned"}
      emptyLabel="No assignable members"
      onChange={(value) => props.onChange(value as UserId | null)}
    />
  );
}

